with gaps as (select *, case when paid_at - lag(paid_at) over (partition by order_id order by paid_at, id) > interval 14 days then 1 else 0 end as is_new_session from payments), sessionized as (select *, sum(is_new_session) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as burst_id from gaps) select case when is_new_session >= 1 then 'HIGH' else 'LOW' end as is_new_session_tier, date_trunc('week', paid_at) as week_start, count_if(method = 'card') as card_events, count(case when status = 'FAILED' then 1 end) as failed_count, sum(case when status = 'SUCCESS' then burst_id else 0 end) as success_burst_id, max(is_new_session) filter (where method = 'promptpay') as promptpay_max_is_new_session from sessionized group by is_new_session_tier, week_start having count_if(method = 'card') >= 1 order by success_burst_id;
